CREATE COLUMN TABLE "TEST_AP"."OPPA" ("AbsEntry" INTEGER CS_INT DEFAULT 1 NOT NULL , "SecLevel" NVARCHAR(20) DEFAULT 'Low', "PwdExp" INTEGER CS_INT DEFAULT 90, "PwdMinLen" INTEGER CS_INT DEFAULT 4, "MinUppers" INTEGER CS_INT DEFAULT 0, "MinLowCase" INTEGER CS_INT DEFAULT 0, "MinDigits" INTEGER CS_INT DEFAULT 0, "MinNonAlph" INTEGER CS_INT DEFAULT 0, "NumPrevPwd" INTEGER CS_INT DEFAULT 0, "NumAuthLoc" INTEGER CS_INT DEFAULT 100, "PwdExample" NVARCHAR(10) DEFAULT 'abcd', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE 